'use strict';
const PUBLIC_NAMES={inicio:'Inicio',obras:'Obras',colecciones:'Colecciones',exposiciones:'Exposiciones',virtual:'Exposición virtual',visita:'Visita',eventos:'Eventos',nosotros:'Nosotros'};
const adminIcons={inicio:'layout-dashboard',obras:'image',autores:'users',colecciones:'layers',ubicaciones:'map-pin',movimientos:'arrow-right-left',prestamos:'landmark',restauraciones:'paintbrush',exposiciones:'panels-top-left',documentos:'files',digitalizacion:'scan',reportes:'chart-no-axes-combined',configuracion:'settings'};
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase();
const EDU='Sitio de demostración desarrollado con fines académicos y educativos. Proyecto no oficial. Los datos, imágenes y contenidos pueden ser ilustrativos.';
const HERO='assets/museum-hero.png', GALLERY='assets/museum-gallery.png';
const defaultContent={
 identity:{name:'Museo Histórico',tagline:'PATRIMONIO Y MEMORIA',logo:'',logoAlt:'Museo Histórico'},
 hero:{title:'Memoria y\nPatrimonio',subtitle:'Historias que nos conectan.\nUn patrimonio que nos pertenece.',eyebrow:'DESCUBRÍ NUESTRA HISTORIA',media:HERO,type:'image',alt:'Escultura en una sala de museo',position:62,cta:'Explorar obras',link:'#public/obras'},
 visit:{title:'Visitá el museo',text:'Un espacio para encontrarnos con la historia, el arte y la memoria.',hours:'Martes a domingo · 10:00 a 19:00',address:'Sede del museo · Dirección a confirmar',contact:'Información de contacto a confirmar',access:'Consultá las condiciones de acceso antes de tu visita.',media:GALLERY,type:'image',alt:'Sala de exposiciones del museo',position:50},
 about:{title:'La memoria se construye entre todos.',text:'Conservamos, investigamos y compartimos el patrimonio para acercar las historias del pasado a las preguntas del presente. Este sitio es una propuesta académica de gestión museológica.',media:GALLERY,type:'image',alt:'Interior del museo',position:50},
 collection:{title:'Colección destacada',text:'Una selección de piezas que nos invita a mirar nuestra historia desde nuevas perspectivas.',media:HERO,type:'image',alt:'Escultura de la colección ilustrativa',position:80},
 banners:{obras:{media:HERO,type:'image',alt:'Patrimonio del museo',position:70},colecciones:{media:HERO,type:'image',alt:'Colecciones del museo',position:70},exposiciones:{media:GALLERY,type:'image',alt:'Exposiciones del museo',position:50},virtual:{media:HERO,type:'image',alt:'Recorrido virtual',position:70},eventos:{media:GALLERY,type:'image',alt:'Sala para encuentros',position:50}},
 sections:[{id:'exposiciones',label:'Exposiciones actuales',visible:true},{id:'encuentros',label:'Eventos y visita',visible:true},{id:'coleccion',label:'Colección destacada',visible:true}],
 exhibitions:[{id:'public-expo-1',title:'Materia y memoria',text:'Objetos, formas y relatos de nuestro patrimonio.',date:'2026-11-01',end:'2026-12-20',room:'Sala principal',status:'actual',published:true,virtual:true,media:HERO,type:'image',alt:'Detalle de una escultura',position:78,workIds:['obra-1','obra-2']},{id:'public-expo-2',title:'Habitar el tiempo',text:'Un recorrido por los espacios que nos definen.',date:'2026-11-05',end:'2026-12-30',room:'Sala de exposiciones',status:'actual',published:true,virtual:false,media:GALLERY,type:'image',alt:'Sala de exposición',position:50,workIds:['obra-2']},{id:'public-expo-3',title:'Territorio y huellas',text:'Paisaje, identidad y memoria compartida.',date:'2026-11-05',end:'2027-02-28',room:'Sala temporal',status:'actual',published:true,virtual:false,media:GALLERY,type:'image',alt:'Espacio cultural',position:20,workIds:['obra-3']}],
 events:[{id:'event-1',title:'Conversatorio',text:'Arte, memoria y patrimonio',date:'2026-11-26',time:'18:00',category:'Conversatorios',published:true,media:GALLERY,type:'image',alt:'Sala del conversatorio',position:50},{id:'event-2',title:'Visita guiada especial',text:'Historias de nuestra colección',date:'2026-12-08',time:'16:00',category:'Visitas guiadas',published:true,media:HERO,type:'image',alt:'Colección del museo',position:80}],
 visuals:{}, featured:['obra-1','obra-2'], footer:EDU
};
let live=structuredClone(defaultContent),draft=null,mediaLibrary=[],audit=[],role=null,identity=null,publicRecords=[],cmsTab='contenido',cmsDirty=false,appReady=false,publicFilter='actual';
let db;
function openStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('museo-patrimonio-v2',1);request.onupgradeneeded=()=>request.result.createObjectStore('state');request.onsuccess=()=>{db=request.result;resolve()};request.onerror=()=>reject(request.error)})}
function getStore(key){return new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function putStore(key,value){return new Promise((resolve,reject)=>{const t=db.transaction('state','readwrite');t.objectStore('state').put(value,key);t.oncomplete=resolve;t.onerror=()=>reject(t.error)})}
async function persistDemo(){await putStore('patrimonio',demo)}
function staffAllowed(){return role==='Administrador'||role==='Director'}
function directorAllowed(){return role==='Director'}
function refreshIcons(){if(window.lucide)lucide.createIcons({attrs:{'stroke-width':1.5}})}
function safeURL(url){if(!url)return '';if(/^assets\/[\w./-]+$/.test(url))return url;if(/^data:(image\/(png|jpeg|webp)|video\/(mp4|webm));base64,[A-Za-z0-9+/=]+$/.test(url))return url;try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}}
function mediaHTML(item,cls='',controls=false){const url=safeURL(item?.media)||HERO;return item?.type==='video'?`<video class="${cls}" src="${esc(url)}" ${controls?'controls':'autoplay muted loop'} playsinline preload="metadata" aria-label="${esc(item.alt||'Video del museo')}" style="object-position:${Number(item.position)||50}% center"></video>`:`<img class="${cls}" src="${esc(url)}" alt="${esc(item?.alt||'Imagen ilustrativa del museo')}" style="object-position:${Number(item?.position)||50}% center" loading="${cls==='hero-media'?'eager':'lazy'}">`}
function bindMediaFallback(){document.querySelectorAll('img').forEach(img=>img.onerror=()=>{img.onerror=null;img.src=HERO;img.alt='Imagen ilustrativa. Recurso no disponible.'})}
function dateLabel(d){return new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short'}).format(new Date((d||'2026-11-01')+'T12:00:00'))}
function brand(c=live){return `<a class="museum-brand" href="#public/inicio">${c.identity.logo?`<img src="${esc(safeURL(c.identity.logo))}" alt="${esc(c.identity.logoAlt)}">`:icon('landmark')}<span>${esc(c.identity.name)}<small>${esc(c.identity.tagline)}</small></span></a>`}
function publicHeader(active,c){return `<header class="public-header">${brand(c)}<button class="mobile-menu" id="mobile-menu" aria-label="Abrir menú" aria-expanded="false">${icon('menu')}</button><nav class="public-nav" id="public-nav">${Object.entries(PUBLIC_NAMES).map(([id,n])=>`<a href="#public/${id}" class="${active===id?'current':''}">${n}</a>`).join('')}</nav><button class="access-button" id="access">${icon(staffAllowed()?'layout-dashboard':'user-round')}${staffAllowed()?'Mi panel':'Acceso'}</button></header>`}
function publicFooter(c){return `<footer class="public-footer"><div>${brand(c)}<div class="footer-links"><a href="#public/exposiciones">Exposiciones</a><a href="#public/colecciones">Colecciones</a><a href="#public/visita">Visita</a><a href="#public/nosotros">Nosotros</a></div><span>© ${new Date().getFullYear()}</span></div><p>${esc(EDU)}</p></footer>`}
function publicHero(c,subpage){const h=c.hero;return `<section class="public-hero ${subpage?'small-hero':''}">${mediaHTML(subpage?c.banners[subpage]||c.about:h,'hero-media')}<div class="hero-copy"><span class="hero-line"></span>${subpage?'':`<p class="hero-kicker">${esc(h.eyebrow)}</p>`}<h1>${esc(subpage?PUBLIC_NAMES[subpage]:h.title).replaceAll('\n','<br>')}</h1><p>${esc(subpage?({obras:'Explorá las piezas y las historias que forman nuestro patrimonio.',colecciones:'Objetos que dialogan, historias que se encuentran.',exposiciones:'Nuevas miradas sobre la historia y el arte.',virtual:'Un recorrido por el museo, estés donde estés.',eventos:'Encuentros, conversaciones y experiencias compartidas.',visita:'Todo lo que necesitás para planificar tu visita.',nosotros:'Conservar, investigar y compartir nuestra memoria.'})[subpage]:h.subtitle).replaceAll('\n','<br>')}</p>${subpage?'':`<div class="hero-buttons"><a class="dark-button" href="${esc(/^#public\//.test(h.link)?h.link:'#public/obras')}">${esc(h.cta)}${icon('arrow-right')}</a><a class="outline-button" href="#public/exposiciones">Ver exposiciones${icon('arrow-right')}</a></div>`}</div>${(subpage?c.banners[subpage]?.type:h.type)==='video'?'<button class="video-toggle" id="video-toggle">Pausar video</button>':''}</section>`}
function exhibitionCard(x){return `<button class="exhibit-card" data-exhibition="${esc(x.id)}">${mediaHTML(x)}<div><h3>${esc(x.title||x.nombre)}</h3><p>${esc(x.text||'Recorrido por el patrimonio del museo.')}</p><span>${dateLabel(x.date||x.fecha_inicio)} — ${dateLabel(x.end||x.fecha_fin)} ${icon('arrow-right')}</span></div></button>`}
function eventsList(events,full=false){return `<div class="event-list ${full?'large-events':''}">${events.map(x=>`<button class="event-row" data-event="${esc(x.id)}"><span class="date-square"><b>${esc(x.date.slice(8,10))}</b>${esc(new Intl.DateTimeFormat('es-AR',{month:'short'}).format(new Date(x.date+'T12:00:00')))}</span>${full?mediaHTML(x):''}<span class="event-copy"><b>${esc(x.title)}</b><span>${esc(x.text)}</span></span><span class="event-time">${esc(x.time)} h</span>${icon('arrow-right')}</button>`).join('')||'<p>No hay eventos publicados.</p>'}</div>`}
function visitBlock(c){return `<div class="visit-feature">${mediaHTML(c.visit)}<div><h2>${esc(c.visit.title)}</h2><p>${esc(c.visit.text)}</p><a class="dark-button" href="#public/visita">Planificá tu visita${icon('arrow-right')}</a></div></div><div class="visit-mini"><div>${icon('clock')}<p><b>Horarios</b>${esc(c.visit.hours)}</p></div><div>${icon('map-pin')}<p><b>Dirección</b>${esc(c.visit.address)}</p></div><div>${icon('info')}<p><b>Información</b>${esc(c.visit.contact)}</p></div></div>`}
function workVisual(o, c = live) {
    const docFoto = o?.documentos?.find(d => /\.(jpg|jpeg|png|webp)(\?|$)/i.test(d.url) || ['JPG', 'PNG', 'WEBP'].includes(d.formato));
    const urlReal = o?.imagen_url || docFoto?.url;
    if (urlReal) {
        return { media: urlReal, type: 'image', alt: o.titulo || 'Imagen de la obra', position: 50 };
    }
    return c.visuals['obras:' + o.id] || { media: HERO, type: 'image', alt: 'Imagen ilustrativa de la colección', position: 70 };
}
function workCard(o,c=live){return `<button class="public-work" data-work="${esc(o.id)}">${mediaHTML(workVisual(o,c))}<div><small>${esc(o.periodo||'PATRIMONIO')}</small><h3>${esc(o.titulo)}</h3><p>${esc(pretty(o.autores))}</p></div></button>`}
async function fetchPublic(k){if(config.mode==='demo'){if(k==='obras')return demo.obras.filter(o=>o.digitalizada);if(k==='exposiciones')return live.exhibitions.filter(x=>x.published);if(k==='colecciones')return demo.colecciones;return []}const path=k==='obras'?'/catalogo?limit=100':k==='exposiciones'?'/catalogo/exposiciones-virtuales':null;if(!path)return [];let r;try{r=await fetch(config.url.replace(/\/$/,'')+path,{signal:AbortSignal.timeout(12000)})}catch{throw Error('El catálogo está temporalmente fuera de servicio. Podés seguir consultando la información del museo.')}if(!r.ok)throw Error('El catálogo público todavía no está habilitado por el servidor. Podés seguir visitando las páginas institucionales.');const data=await r.json();return data.resultados||[]}
async function renderPublic(route,c=live,preview=false){const [active='inicio',id]=route.split('/');let content='',exhibitions=c.exhibitions.filter(x=>x.published),events=c.events.filter(x=>x.published);const errorBox=e=>`<div class="public-empty">${icon('info')}<h2>Catálogo no disponible</h2><p>${esc(e.message)}</p></div>`;
if(active==='inicio'){content=publicHero(c);content+='<div class="public-content">';for(const section of c.sections.filter(s=>s.visible)){if(section.id==='exposiciones')content+=`<section><div class="public-section-head"><h2>Exposiciones actuales</h2><a href="#public/exposiciones">Ver todas ${icon('arrow-right')}</a></div><div class="exhibit-grid">${exhibitions.filter(x=>x.status==='actual').slice(0,3).map(exhibitionCard).join('')}</div></section>`;if(section.id==='encuentros')content+=`<section class="encounters"><div><div class="public-section-head"><h2>Próximos eventos</h2><a href="#public/eventos">Ver agenda ${icon('arrow-right')}</a></div>${eventsList(events.slice(0,2))}</div>${visitBlock(c)}</section>`;if(section.id==='coleccion')content+=`<section class="collection-feature"><div><h2>${esc(c.collection.title)}</h2><p>${esc(c.collection.text)}</p><a class="dark-button" href="#public/colecciones">Explorar colección${icon('arrow-right')}</a></div>${mediaHTML(c.collection)}</section>`}content+='</div>'}
else if(active==='exposiciones'||active==='virtual'){let ex=exhibitions;if(active==='virtual')ex=ex.filter(x=>x.virtual);if(config.mode==='api'){try{ex=await fetchPublic('exposiciones');ex=ex.map(x=>({...x,title:x.nombre,date:x.fecha_inicio,end:x.fecha_fin,media:HERO,type:'image'}))}catch(e){content=errorBox(e)}}if(id){const x=ex.find(x=>x.id===id);content=x?`<div class="detail-public"><a class="back-link" href="#public/${active}">${icon('arrow-left')} Volver a exposiciones</a><div class="detail-grid">${mediaHTML(x,'detail-image')}<div><span class="eyebrow">${active==='virtual'?'EXPOSICIÓN VIRTUAL':'EXPOSICIÓN'}</span><h1>${esc(x.title)}</h1><p>${esc(x.text||'Explorá las obras de esta exposición.')}</p><p>${dateLabel(x.date)} — ${dateLabel(x.end)}</p><p>${esc(x.room||'')}</p></div></div><h2>Obras del recorrido</h2><div id="virtual-works" class="public-work-grid"></div></div>`:'<div class="public-empty">Esta exposición no está publicada.</div>';publicRecords=config.mode==='demo'?demo.obras.filter(o=>x?.workIds?.includes(o.id)&&o.digitalizada):[];if(config.mode==='api'&&x){try{const r=await fetch(config.url.replace(/\/$/,'')+'/catalogo/exposiciones-virtuales/'+encodeURIComponent(id));if(!r.ok)throw Error('No se pudo cargar el recorrido');publicRecords=(await r.json()).obras||[]}catch(e){content+=errorBox(e)}}}else if(!content)content=publicHero(c,active)+`<div class="public-content"><div class="filter-tabs">${(active==='virtual'?['todas']:['actual','proxima','anterior','todas']).map((s,i)=>`<button class="${i===0?'selected':''}" data-expo-filter="${s}">${({actual:'Actuales',proxima:'Próximas',anterior:'Anteriores',todas:'Todas'})[s]}</button>`).join('')}</div><div class="exhibitions-list" id="exhibition-results">${ex.map(exhibitionCard).join('')||'<p>No hay exposiciones publicadas.</p>'}</div></div>`;publicFilter=active==='virtual'?'todas':'actual';window.currentPublicExpos=ex}
else if(active==='obras'||active==='colecciones'){try{publicRecords=await fetchPublic(active);if(active==='obras'){if(id){const o=publicRecords.find(o=>o.id===id);content=o?`<div class="detail-public"><a class="back-link" href="#public/obras">${icon('arrow-left')} Volver a las obras</a><div class="detail-grid">${mediaHTML(workVisual(o,c),'detail-image')}<div><span class="eyebrow">${esc(o.periodo||'PATRIMONIO')}</span><h1>${esc(o.titulo)}</h1><p>${esc(pretty(o.autores))}</p><dl><dt>Técnica</dt><dd>${esc(o.tecnica||'Sin información pública')}</dd><dt>Período</dt><dd>${esc(o.periodo||'Sin información')}</dd></dl><p class="subtle">Imagen ilustrativa para la demostración académica.</p></div></div></div>`:'<div class="public-empty">La obra no está disponible en el catálogo público.</div>'}else content=publicHero(c,active)+`<div class="public-content"><div class="public-search">${icon('search')}<input id="public-search" placeholder="Buscar obras, autores o períodos…" aria-label="Buscar obras"><select id="public-period" aria-label="Filtrar período"><option value="">Todos los períodos</option>${[...new Set(publicRecords.map(o=>o.periodo).filter(Boolean))].map(p=>`<option>${esc(p)}</option>`).join('')}</select><button id="clear-public">Limpiar</button></div><div class="public-work-grid" id="public-works"></div></div>`}else{const collections=publicRecords;content=publicHero(c,active)+`<div class="public-content"><div class="public-work-grid">${collections.map(x=>`<button class="public-work" data-collection="${esc(x.id)}">${mediaHTML(c.visuals['colecciones:'+x.id]||c.collection)}<div><h3>${esc(x.nombre)}</h3><p>${esc(x.descripcion)}</p><small>${x.obras?.length||0} obras</small></div></button>`).join('')||'<p>Las colecciones públicas todavía no están disponibles.</p>'}</div></div>`}}catch(e){content=publicHero(c,active)+errorBox(e)}}
else if(active==='eventos'){const x=events.find(x=>x.id===id);content=id?(x?`<div class="detail-public"><a class="back-link" href="#public/eventos">${icon('arrow-left')} Volver a eventos</a><div class="detail-grid">${mediaHTML(x,'detail-image')}<div><span class="eyebrow">${esc(x.category)}</span><h1>${esc(x.title)}</h1><p>${esc(x.text)}</p><p>${dateLabel(x.date)} · ${esc(x.time)} h</p><p>Consultá disponibilidad e información de acceso con el museo.</p><a class="dark-button" href="#public/visita">Información de visita${icon('arrow-right')}</a></div></div></div>`:'<div class="public-empty">Este evento no está publicado.</div>'):publicHero(c,active)+`<div class="public-content"><div class="filter-tabs">${['Todos','Conversatorios','Visitas guiadas','Talleres'].map((s,i)=>`<button class="${i===0?'selected':''}" data-event-filter="${s}">${s}</button>`).join('')}</div><div id="events-results">${eventsList(events,true)}</div></div>`}
else if(active==='visita'){content=publicHero(c,active)+`<div class="public-content visit-page"><div class="visit-info"><section>${icon('clock')}<h2>Horarios</h2><p>${esc(c.visit.hours)}</p></section><section>${icon('map-pin')}<h2>Dirección</h2><p>${esc(c.visit.address)}</p></section><section>${icon('accessibility')}<h2>Acceso y accesibilidad</h2><p>${esc(c.visit.access)}</p></section><section>${icon('mail')}<h2>Información</h2><p>${esc(c.visit.contact)}</p></section></div>${mediaHTML(c.visit,'visit-page-image')}</div>`}
else if(active==='nosotros'){content=publicHero(c,active)+`<div class="public-content about-layout">${mediaHTML(c.about)}<div><span class="eyebrow">PATRIMONIO Y MEMORIA</span><h2>${esc(c.about.title)}</h2><p>${esc(c.about.text)}</p><a class="outline-button" href="#public/colecciones">Conocé las colecciones${icon('arrow-right')}</a></div></div>`}
else {location.hash='public/inicio';return}
if(!preview&&!location.hash.startsWith('#public/')&&location.hash)return;
$('#public-app').innerHTML=(preview?'<div class="preview-bar"><b>Vista previa · Borrador sin publicar</b><button id="leave-preview">Volver al editor</button></div>':'')+`<div class="public-shell">${publicHeader(active,c)}${content}${publicFooter(c)}</div>`;
$('#access').onclick=()=>{location.hash=staffAllowed()?'admin/inicio':'acceso'};$('#mobile-menu').onclick=e=>{const nav=$('#public-nav');nav.classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',nav.classList.contains('open'))};if($('#leave-preview'))$('#leave-preview').onclick=()=>location.hash='admin/contenidos';if($('#video-toggle'))$('#video-toggle').onclick=e=>{const video=$('.hero-media');if(video.paused){video.play();e.target.textContent='Pausar video'}else{video.pause();e.target.textContent='Reproducir video'}};if($('#public-search')){const filter=()=>{const q=normalize($('#public-search').value),p=$('#public-period').value;$('#public-works').innerHTML=publicRecords.filter(o=>normalize([o.titulo,pretty(o.autores),o.periodo].join(' ')).includes(q)&&(!p||o.periodo===p)).map(o=>workCard(o,c)).join('')||'<p>No encontramos obras con estos filtros.</p>';bindPublicLinks()};$('#public-search').oninput=filter;$('#public-period').onchange=filter;$('#clear-public').onclick=()=>{$('#public-search').value='';$('#public-period').value='';filter()};filter()}
if($('#virtual-works'))$('#virtual-works').innerHTML=publicRecords.map(o=>workCard(o,c)).join('')||'<p>No hay obras digitalizadas publicadas en este recorrido.</p>';
document.querySelectorAll('[data-expo-filter]').forEach(b=>b.onclick=()=>{publicFilter=b.dataset.expoFilter;document.querySelectorAll('[data-expo-filter]').forEach(t=>t.classList.toggle('selected',t===b));$('#exhibition-results').innerHTML=window.currentPublicExpos.filter(x=>publicFilter==='todas'||x.status===publicFilter||config.mode==='api').map(exhibitionCard).join('')||'<p>No hay exposiciones en esta categoría.</p>';bindPublicLinks();refreshIcons()});if(active==='exposiciones'&&!id&&$('#exhibition-results')){const b=$('[data-expo-filter="actual"]');if(b)b.click()}
document.querySelectorAll('[data-event-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-event-filter]').forEach(t=>t.classList.toggle('selected',t===b));$('#events-results').innerHTML=eventsList(events.filter(e=>b.dataset.eventFilter==='Todos'||e.category===b.dataset.eventFilter),true);bindPublicLinks();refreshIcons()});bindPublicLinks();if(preview){document.querySelectorAll('#public-app a[href^="#public/"]').forEach(a=>a.href=a.getAttribute('href').replace('#public/','#preview/'));}refreshIcons();bindMediaFallback();}
function bindPublicLinks(){document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>location.hash='public/obras/'+b.dataset.work);document.querySelectorAll('[data-exhibition]').forEach(b=>b.onclick=()=>location.hash='public/'+(location.hash.includes('/virtual')?'virtual':'exposiciones')+'/'+b.dataset.exhibition);document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>location.hash='public/eventos/'+b.dataset.event);document.querySelectorAll('[data-collection]').forEach(b=>b.onclick=()=>{const x=publicRecords.find(x=>x.id===b.dataset.collection);modal(x.nombre,`<p>${esc(x.descripcion)}</p><ul>${(x.obras||[]).map(o=>`<li><a href="#public/obras/${esc(o.id_obra)}" data-close-dialog>${esc(o.titulo)}</a></li>`).join('')}</ul>`);document.querySelectorAll('[data-close-dialog]').forEach(a=>a.onclick=()=>$('#modal').close())})}
function showLogin(){document.body.className='public-mode';$('#admin-app').hidden=true;$('#public-app').hidden=false;$('#public-app').innerHTML=`<div class="public-shell">${publicHeader('',live)}<section class="login-layout">${mediaHTML(live.hero,'login-image')}<div class="login-card"><span class="eyebrow">EQUIPO DEL MUSEO</span><h1>Acceso institucional</h1><p>El sitio público es de libre acceso. Este espacio está reservado al equipo de gestión.</p>${config.mode==='demo'?`<div class="demo-label">Demostración académica · Sin credenciales reales</div><button class="role-choice" data-role="Administrador">${icon('briefcase-business')}<span><b>Administrador Demo</b><small>Gestión de registros y patrimonio</small></span>${icon('arrow-right')}</button><button class="role-choice" data-role="Director">${icon('layout-dashboard')}<span><b>Director Demo</b><small>Gestión integral y edición del sitio</small></span>${icon('arrow-right')}</button><details><summary>Conectar una identidad real</summary>${tokenForm()}</details>`:tokenForm()}<a class="back-link" href="#public/inicio">${icon('arrow-left')} Volver al sitio público</a><div id="login-error" role="alert"></div></div></section>${publicFooter(live)}</div>`;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;identity={name:role+' Demo',demo:true};sessionStorage.setItem('museo-demo-role',role);location.hash='admin/inicio'});if($('#identity-form'))$('#identity-form').onsubmit=authenticate;$('#access').onclick=()=>{};$('#mobile-menu').onclick=()=>$('#public-nav').classList.toggle('open');refreshIcons();bindMediaFallback()}
function tokenForm(){return `<form id="identity-form"><label>URL del backend<input name="backend" type="url" required value="${esc(config.url)}"></label><label>Token de acceso institucional<input name="accessToken" type="password" required autocomplete="off"></label><p class="subtle">El servidor debe devolver tu rol mediante /usuarios/yo. No se asignan permisos desde el selector Demo.</p><button class="dark-button" type="submit">Verificar identidad${icon('arrow-right')}</button></form>`}
async function authenticate(e){e.preventDefault();const oldConfig=config,oldToken=token;e.submitter.disabled=true;try{config={mode:'api',url:e.target.backend.value.replace(/\/$/,'')};token=e.target.accessToken.value.trim();const me=await api('/usuarios/yo');if(!['Administrador','Director'].includes(me.rol))throw Error('Tu identidad no tiene acceso a la administración.');role=me.rol;identity={name:me.nombre||me.rol,demo:false};sessionStorage.removeItem('museo-demo-role');localStorage.setItem('museo-config',JSON.stringify(config));cache={};location.hash='admin/inicio'}catch(err){config=oldConfig;token=oldToken;$('#login-error').innerHTML=`<div class="note error">${esc(err.message)}</div>`}finally{e.submitter.disabled=false}}
function adminShell(){document.body.className='admin-mode';$('#admin-app').hidden=false;$('#public-app').hidden=true;$('.brand').innerHTML=`${icon('landmark')}<span>MUSEO HISTÓRICO<small>Patrimonio y memoria</small></span>`;$('.brand').href='#public/inicio';$('.sidefoot').innerHTML=`<span class="avatar">${icon('user-round')}</span><div>${esc(identity?.name||role)}<small>${identity?.demo?'Perfil de demostración':'Identidad verificada'}</small></div>`;$('#connection').onclick=()=>location.hash='admin/configuracion';}
function enhanceAdmin(){const nav=$('#nav');nav.innerHTML=Object.entries(names).map(([k,n])=>`<a class="${page===k?'active':''}" href="#admin/${k}">${icon(adminIcons[k])}${n}</a>`).join('')+(directorAllowed()?`<div class="nav-divider">DIRECCIÓN DEL MUSEO</div><a class="${page==='contenidos'?'active':''}" href="#admin/contenidos">${icon('sliders-horizontal')}Editor del sitio</a><a class="${page==='multimedia'?'active':''}" href="#admin/multimedia">${icon('images')}Biblioteca multimedia</a>`:'')+`<div class="nav-divider">CUENTA</div><a href="#public/inicio">${icon('external-link')}Ver sitio público</a><a href="#salir">${icon('log-out')}Cerrar sesión</a>`;$('.navlabel').textContent=role==='Director'?'DIRECCIÓN Y PATRIMONIO':'GESTIÓN PATRIMONIAL';$('footer').innerHTML=`Museo Histórico <span>Proyecto académico · ${esc(role)}</span>`;document.querySelectorAll('.art').forEach(el=>el.outerHTML=mediaHTML(live.hero,'admin-hero-image'));document.querySelectorAll('.thumb').forEach((el,i)=>el.outerHTML=mediaHTML(workVisual(rows[i]||{}),'admin-card-image'));if(page==='configuracion'){const settings=$('#settings');if(settings){const onsubmit=settings.onsubmit;settings.onsubmit=e=>{if(settings.mode.value==='api'){e.preventDefault();config={mode:'api',url:settings.url.value.replace(/\/$/,'')};localStorage.setItem('museo-config',JSON.stringify(config));token='';role=null;identity=null;cache={};sessionStorage.removeItem('museo-demo-role');toast('Verificá tu identidad para usar esta conexión.');location.hash='acceso';return}onsubmit(e)}}}refreshIcons();bindMediaFallback()}
async function render(){if(!appReady)return;const route=location.hash.slice(1)||'public/inicio';if(route==='salir'){role=null;identity=null;token='';cache={};sessionStorage.removeItem('museo-demo-role');location.hash='public/inicio';return}if(route==='acceso'){showLogin();return}if(route.startsWith('admin/')){if(!staffAllowed()){showLogin();return}adminShell();page=route.slice(6);if(['contenidos','multimedia'].includes(page)){if(!directorAllowed()){$('#main').innerHTML=title('Acceso restringido','Solo el Director puede modificar el contenido visual del sitio.');enhanceAdmin();return}await renderCMS(page==='multimedia'?'biblioteca':cmsTab);enhanceAdmin();return}await renderAdmin();enhanceAdmin();return}if(route==='preview'||route.startsWith('preview/')){if(!directorAllowed()){location.hash='public/inicio';return}document.body.className='public-mode';$('#admin-app').hidden=true;$('#public-app').hidden=false;await renderPublic(route==='preview'?'inicio':route.slice(8),draft||live,true);return}document.body.className='public-mode';$('#admin-app').hidden=true;$('#public-app').hidden=false;await renderPublic(route.startsWith('public/')?route.slice(7):'inicio')}
function getPath(obj,path){return path.split('.').reduce((o,k)=>o?.[k],obj)}
function setPath(obj,path,value){const keys=path.split('.');const key=keys.pop();let target=obj;for(const k of keys){target[k]??={};target=target[k]}target[key]=value}
function localCMSAllowed(){if(!directorAllowed())throw Error('Solo el Director puede editar el sitio.');if(config.mode!=='demo')throw Error('El backend actual no tiene endpoints de contenido o multimedia. Esta edición está disponible en demostración local.');}
async function logCMS(action,entity){audit.unshift({date:new Date().toISOString(),user:identity?.name||role,action,entity});audit=audit.slice(0,100);await putStore('audit',audit)}
async function saveDraft(silent=false){localCMSAllowed();await putStore('draft',draft);cmsDirty=false;if($('#draft-status'))$('#draft-status').textContent='Borrador guardado · Solo Director';if(!silent)toast('Borrador guardado en este navegador');}
async function publishDraft(){localCMSAllowed();if(!draft.hero.title.trim())throw Error('Completá el título del hero antes de publicar.');if(!safeURL(draft.hero.media))throw Error('El hero debe tener una imagen o video válido.');await putStore('previous-live',live);await putStore('live',draft);live=structuredClone(draft);await saveDraft(true);await logCMS('Publicación de contenido','Sitio público');toast('Publicado en la demo de este navegador');await renderCMS(cmsTab)}
function cmsText(path,label,type='text'){const value=getPath(draft,path)??'';return `<label class="${type==='textarea'?'full':''}">${label}${type==='textarea'?`<textarea data-content="${path}" rows="3">${esc(value)}</textarea>`:`<input data-content="${path}" value="${esc(value)}">`}</label>`}
function slotCard(path,label){const x=getPath(draft,path);return `<article class="asset-slot">${mediaHTML(x,'asset-thumbnail',true)}<div><small>${esc(label)}</small><b>${esc(x.title||x.alt||label)}</b><span>${x.type==='video'?'Video':'Imagen'} · Posición ${x.position||50}%</span><button data-slot="${esc(path)}">${icon('image-plus')} Cambiar recurso</button></div></article>`}
function mediaSlots(){const slots=[['hero','Hero de inicio'],['visit','Página Visita'],['about','Página Nosotros'],['collection','Colección destacada']];for(const k of Object.keys(draft.banners))slots.push(['banners.'+k,'Banner · '+PUBLIC_NAMES[k]]);draft.exhibitions.forEach((x,i)=>slots.push(['exhibitions.'+i,'Exposición · '+x.title]));draft.events.forEach((x,i)=>slots.push(['events.'+i,'Evento · '+x.title]));for(const [key,value] of Object.entries(draft.visuals))slots.push(['visuals.'+key,value.title||key]);return slots}
async function renderCMS(tabName='contenido'){cmsTab=tabName;if(!draft)draft=structuredClone(live);$('#crumb').textContent=page==='multimedia'?'Biblioteca multimedia':'Editor del sitio';$('#main').innerHTML=title('La imagen de tu museo.','Editá el contenido, cuidá cada detalle y revisá antes de publicar.',`<button id="preview-site">${icon('eye')} Vista previa</button>`)+`<div class="cms-notice">${icon('info')}<div><b>${config.mode==='demo'?'Edición local de demostración':'Edición de contenidos no conectada'}</b><span>${config.mode==='demo'?'Los borradores y archivos se conservan al recargar este navegador. No se sincronizan con otros visitantes.':'El backend del ZIP no expone un CMS ni almacenamiento multimedia. No se guardarán cambios de producción desde este panel.'}</span></div></div><div class="cms-tabs">${[['contenido','Contenido del sitio'],['visuales','Imágenes y videos'],['biblioteca','Biblioteca'],['publicacion','Publicación e historial']].map(([id,n])=>`<button class="${cmsTab===id?'selected':''}" data-cms-tab="${id}">${n}</button>`).join('')}</div><div id="cms-body"></div><div class="cms-savebar"><span id="draft-status">Borrador ${cmsDirty?'con cambios sin guardar':'guardado'} · Solo Director</span><div><button id="save-draft">Guardar borrador</button><button class="primary" id="publish-draft">Publicar en la demo</button></div></div>`;
const body=$('#cms-body');if(cmsTab==='contenido'){body.innerHTML=`<div class="cms-columns"><div><section class="cms-panel"><div class="cms-heading"><span>01</span><div><h2>Identidad y portada</h2><p>La primera mirada al museo.</p></div></div><div class="formgrid">${cmsText('identity.name','Nombre del museo')}${cmsText('identity.tagline','Bajada institucional')}${cmsText('hero.eyebrow','Texto superior')}${cmsText('hero.cta','Botón principal')}${cmsText('hero.title','Título del hero','textarea')}${cmsText('hero.subtitle','Subtítulo','textarea')}<label>Destino del botón<select data-content="hero.link">${Object.entries(PUBLIC_NAMES).map(([k,n])=>`<option value="#public/${k}" ${draft.hero.link==='#public/'+k?'selected':''}>${n}</option>`).join('')}</select></label></div><button id="edit-logo">${icon('image-plus')} Editar logotipo</button></section><section class="cms-panel"><div class="cms-heading"><span>02</span><div><h2>Visita e información</h2><p>Información útil para quienes nos visitan.</p></div></div><div class="formgrid">${cmsText('visit.title','Título')}${cmsText('visit.hours','Horarios')}${cmsText('visit.address','Dirección')}${cmsText('visit.contact','Contacto')}${cmsText('visit.text','Introducción','textarea')}${cmsText('visit.access','Acceso y accesibilidad','textarea')}</div></section><section class="cms-panel"><div class="cms-heading"><span>03</span><div><h2>Nosotros y colección</h2></div></div><div class="formgrid">${cmsText('about.title','Título de Nosotros')}${cmsText('collection.title','Título de colección')}${cmsText('about.text','Texto institucional','textarea')}${cmsText('collection.text','Introducción a la colección','textarea')}</div></section></div><div><section class="cms-panel"><h2>Portada del sitio</h2>${slotCard('hero','Imagen o video principal')}<h3>Secciones de inicio</h3><div id="section-order">${draft.sections.map((s,i)=>`<div class="section-order"><label><input type="checkbox" data-visible="${s.id}" ${s.visible?'checked':''}>${esc(s.label)}</label><button data-move="${i}:up" aria-label="Subir ${esc(s.label)}" ${i===0?'disabled':''}>${icon('chevron-up')}</button><button data-move="${i}:down" aria-label="Bajar ${esc(s.label)}" ${i===draft.sections.length-1?'disabled':''}>${icon('chevron-down')}</button></div>`).join('')}</div></section><section class="cms-panel"><h2>Exposiciones publicadas</h2>${draft.exhibitions.map((x,i)=>`<div class="cms-item"><span>${esc(x.title)}<small>${x.published?'Visible':'Borrador'}${x.virtual?' · Recorrido virtual':''}</small></span><button data-edit-expo="${i}">Editar</button></div>`).join('')}<button id="new-expo">${icon('plus')} Agregar contenido de exposición</button></section><section class="cms-panel"><h2>Agenda de eventos</h2>${draft.events.map((x,i)=>`<div class="cms-item"><span>${esc(x.title)}<small>${x.published?'Visible':'Borrador'}</small></span><button data-edit-event="${i}">Editar</button></div>`).join('')}<button id="new-event">${icon('plus')} Agregar evento</button></section></div></div>`}
else if(cmsTab==='visuales'){for(const group of ['obras','autores','colecciones']){if(config.mode==='demo')for(const r of demo[group]){const key=group+':'+r.id;draft.visuals[key]??={media:group==='autores'?GALLERY:HERO,type:'image',alt:r.titulo||r.nombre,title:(names[group]||group)+' · '+(r.titulo||r.nombre),position:70}}}body.innerHTML=`<div class="sectionhead"><h2>Todos los recursos del sitio</h2><span class="subtle">Hero, páginas, portadas y fichas</span></div><div class="asset-grid">${mediaSlots().map(([p,n])=>slotCard(p,n)).join('')}</div>`}
else if(cmsTab==='biblioteca'){body.innerHTML=`<section class="cms-panel"><div class="sectionhead"><div><h2>Biblioteca multimedia</h2><p>Imágenes y videos disponibles para tus páginas.</p></div><button class="primary" id="upload-media">${icon('upload')} Subir archivo</button></div><div class="toolbar"><input id="media-search" placeholder="Buscar archivo o descripción…" aria-label="Buscar archivos"><select id="media-type" aria-label="Tipo de archivo"><option value="">Todos los formatos</option><option value="image">Imágenes</option><option value="video">Videos</option></select></div><div id="media-grid" class="asset-grid"></div></section>`}
else{body.innerHTML=`<section class="cms-panel"><h2>Publicación y versiones</h2><p>El borrador no modifica las páginas públicas hasta que lo publiques. La publicación de demostración se guarda en este navegador.</p><div class="actions"><button id="restore-version">Restaurar publicación anterior al borrador</button><button id="export-content">Exportar contenido y archivos</button><button id="import-content">Importar contenido</button></div><h3>Actividad local</h3><div class="tablewrap"><table><thead><tr><th>Fecha</th><th>Perfil</th><th>Acción</th></tr></thead><tbody>${audit.map(x=>`<tr><td>${esc(new Date(x.date).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires'}))}</td><td>${esc(x.user)}</td><td>${esc(x.action)}</td></tr>`).join('')||'<tr><td colspan="3">Todavía no hay actividad editorial.</td></tr>'}</tbody></table></div><p class="subtle">Historial de demostración. No reemplaza una auditoría protegida en el servidor.</p></section>`}
bindCMS();refreshIcons();bindMediaFallback()}
function markDirty(){cmsDirty=true;if($('#draft-status'))$('#draft-status').textContent='Hay cambios sin guardar · Solo Director'}
function bindCMS(){document.querySelectorAll('[data-cms-tab]').forEach(b=>b.onclick=()=>renderCMS(b.dataset.cmsTab));document.querySelectorAll('[data-content]').forEach(el=>el.oninput=()=>{if(config.mode!=='demo')return;setPath(draft,el.dataset.content,el.value);markDirty()});document.querySelectorAll('[data-visible]').forEach(el=>el.onchange=()=>{try{localCMSAllowed();draft.sections.find(x=>x.id===el.dataset.visible).visible=el.checked;markDirty()}catch(e){toast(e.message)}});document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{try{localCMSAllowed();const [i,dir]=el.dataset.move.split(':'),j=Number(i)+(dir==='up'?-1:1);[draft.sections[i],draft.sections[j]]=[draft.sections[j],draft.sections[i]];markDirty();renderCMS(cmsTab)}catch(e){toast(e.message)}});document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>editSlot(b.dataset.slot));$('#preview-site').onclick=()=>location.hash='preview';$('#save-draft').onclick=async()=>{try{await saveDraft()}catch(e){toast(e.message)}};$('#publish-draft').onclick=async e=>{e.target.disabled=true;try{await publishDraft()}catch(err){toast(err.message)}finally{e.target.disabled=false}};if(config.mode!=='demo'){document.querySelectorAll('#cms-body input,#cms-body textarea,#cms-body select,#save-draft,#publish-draft').forEach(el=>el.disabled=true)}if($('#edit-logo'))$('#edit-logo').onclick=editLogo;document.querySelectorAll('[data-edit-expo]').forEach(b=>b.onclick=()=>editEditorial('exhibitions',Number(b.dataset.editExpo)));document.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=()=>editEditorial('events',Number(b.dataset.editEvent)));if($('#new-expo'))$('#new-expo').onclick=()=>editEditorial('exhibitions');if($('#new-event'))$('#new-event').onclick=()=>editEditorial('events');if($('#upload-media'))$('#upload-media').onclick=()=>uploadDialog();if($('#media-search')){$('#media-search').oninput=renderLibrary;$('#media-type').onchange=renderLibrary;renderLibrary()}if($('#restore-version'))$('#restore-version').onclick=async()=>{try{localCMSAllowed();const old=await getStore('previous-live');if(!old)throw Error('No hay una publicación anterior.');draft=old;markDirty();renderCMS('contenido');toast('Versión anterior restaurada al borrador')}catch(e){toast(e.message)}};if($('#export-content'))$('#export-content').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:2,draft,live,mediaLibrary},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='museo-contenidos.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};if($('#import-content'))$('#import-content').onclick=()=>{try{localCMSAllowed();modal('Importar contenido',`<p>Importá una exportación de este editor. Se cargará como borrador, sin cambiar la publicación actual.</p><input type="file" id="import-file" accept="application/json"><div id="import-error"></div>`);$('#import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>150*1024*1024)throw Error('La importación supera 150 MB.');const d=JSON.parse(await f.text());if(d.version!==2||!d.draft?.hero||!Array.isArray(d.draft.sections)||!Array.isArray(d.draft.events)||!Array.isArray(d.draft.exhibitions)||!d.draft.identity||!d.draft.visit||!d.draft.about||!d.draft.collection||!d.draft.banners||!d.draft.visuals)throw Error('El archivo no tiene el formato de este editor.');draft=d.draft;mediaLibrary=Array.isArray(d.mediaLibrary)?d.mediaLibrary:[];await putStore('media',mediaLibrary);await saveDraft(true);$('#modal').close();renderCMS('contenido');toast('Importado como borrador')}catch(e){$('#import-error').textContent=e.message}}}catch(e){toast(e.message)}}}
function editSlot(path){try{localCMSAllowed()}catch(e){toast(e.message);return}const item=getPath(draft,path);modal('Editar imagen o video',`<div class="media-editor-preview">${mediaHTML(item,'',true)}</div><form id="slot-form"><div class="formgrid"><label class="full">Recurso de la biblioteca<select id="slot-library"><option value="">Conservar recurso / ingresar URL</option>${mediaLibrary.map(x=>`<option value="${esc(x.id)}">${esc(x.name)} (${x.type==='video'?'video':'imagen'})</option>`).join('')}</select></label><label class="full">URL de imagen o video<input name="mediaurl" type="text" value="${esc(item.media?.startsWith('data:')?'':item.media)}" placeholder="https://…"></label><label>Formato<select name="type"><option value="image" ${item.type==='image'?'selected':''}>Imagen</option><option value="video" ${item.type==='video'?'selected':''}>Video</option></select></label><label>Enfoque horizontal (%)<input name="position" type="number" min="0" max="100" value="${item.position??50}"></label><label class="full">Descripción accesible<input name="alt" required value="${esc(item.alt)}"></label></div><div class="actions"><button type="button" id="slot-upload">Subir archivo</button><button type="button" id="slot-preview">Previsualizar recurso</button><button class="primary">Aplicar al borrador</button></div><div id="slot-error" role="alert"></div></form>`);let current=item.media;$('#slot-library').onchange=e=>{const asset=mediaLibrary.find(a=>a.id===e.target.value);if(asset){current=asset.media;$('#slot-form').type.value=asset.type;$('#slot-form').alt.value=asset.alt;$('#slot-form').mediaurl.value='';$('.media-editor-preview').innerHTML=mediaHTML(asset,'',true)}};$('#slot-form').mediaurl.oninput=e=>{current=e.target.value};$('#slot-upload').onclick=()=>uploadDialog(asset=>{editSlot(path);const select=$('#slot-library');select.value=asset.id;select.dispatchEvent(new Event('change'))});$('#slot-preview').onclick=()=>{if(!safeURL(current)){$('#slot-error').textContent='Ingresá una URL HTTP/HTTPS válida o seleccioná un archivo.';return}$('.media-editor-preview').innerHTML=mediaHTML({media:current,type:$('#slot-form').type.value,alt:$('#slot-form').alt.value,position:$('#slot-form').position.value},'',true)};$('#slot-form').onsubmit=e=>{e.preventDefault();try{localCMSAllowed();if(!safeURL(current))throw Error('Seleccioná un archivo o una URL HTTP/HTTPS válida.');Object.assign(item,{media:current,type:e.target.type.value,position:Number(e.target.position.value),alt:e.target.alt.value.trim()});markDirty();$('#modal').close();renderCMS(cmsTab);toast('Recurso actualizado en el borrador')}catch(e){$('#slot-error').textContent=e.message}};refreshIcons()}
function editLogo(){try{localCMSAllowed()}catch(e){toast(e.message);return}modal('Logotipo institucional',`<form id="logo-form"><label>Imagen de la biblioteca<select name="asset"><option value="">Usar símbolo institucional predeterminado</option>${mediaLibrary.filter(x=>x.type==='image').map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></label><label>Texto alternativo<input name="alt" required value="${esc(draft.identity.logoAlt)}"></label><div class="actions"><button type="button" id="logo-upload">Subir logotipo</button><button class="primary">Aplicar al borrador</button></div></form>`);$('#logo-upload').onclick=()=>uploadDialog(asset=>{editLogo();$('#logo-form').asset.value=asset.id});$('#logo-form').onsubmit=e=>{e.preventDefault();const asset=mediaLibrary.find(x=>x.id===e.target.asset.value);draft.identity.logo=asset?.media||'';draft.identity.logoAlt=e.target.alt.value;markDirty();$('#modal').close();toast('Logotipo actualizado en el borrador')}}
async function readMedia(file){if(!file)throw Error('Seleccioná un archivo.');const bytes=new Uint8Array(await file.slice(0,32).arrayBuffer());const text=new TextDecoder().decode(bytes);let mime='';if(bytes[0]===137&&text.slice(1,4)==='PNG')mime='image/png';else if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255)mime='image/jpeg';else if(text.slice(0,4)==='RIFF'&&text.slice(8,12)==='WEBP')mime='image/webp';else if(text.slice(4,8)==='ftyp')mime='video/mp4';else if(bytes[0]===26&&bytes[1]===69&&bytes[2]===223&&bytes[3]===163)mime='video/webm';if(!mime)throw Error('Formato no admitido. Usá JPG, PNG, WebP, MP4 o WebM.');const type=mime.startsWith('image')?'image':'video';if(file.size>(type==='image'?12:50)*1024*1024)throw Error(type==='image'?'La imagen supera 12 MB.':'El video supera 50 MB.');const normalized=new Blob([file],{type:mime});const media=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('No se pudo leer el archivo.'));reader.readAsDataURL(normalized)});if(type==='image'){await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=()=>reject(Error('La imagen no pudo decodificarse.'));img.src=media})}else{await new Promise((resolve,reject)=>{const video=document.createElement('video');video.preload='metadata';const timer=setTimeout(()=>reject(Error('No se pudo verificar el video. Probá con un MP4 H.264 o WebM compatible.')),12000);video.onloadedmetadata=()=>{clearTimeout(timer);resolve()};video.onerror=()=>{clearTimeout(timer);reject(Error('El video no se puede reproducir.'))};video.src=media})}return {id:crypto.randomUUID(),name:file.name.replace(/[^a-zA-Z0-9._ -]/g,'_'),media,type,mime,size:file.size,alt:file.name,position:50,created:new Date().toISOString()}}
function uploadDialog(after){try{localCMSAllowed()}catch(e){toast(e.message);return}modal('Agregar recurso a la biblioteca',`<form id="upload-form"><div class="upload-zone">${icon('upload')}<h2>Imágenes y videos del museo</h2><p>JPG, PNG y WebP hasta 12 MB.<br>MP4 y WebM hasta 50 MB.</p><input name="file" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" required></div><label>Descripción accesible<input name="alt" required placeholder="Describí brevemente la imagen o el video"></label><div id="upload-error" role="alert"></div><div class="actions"><button class="primary">Guardar archivo</button></div></form>`);$('#upload-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{localCMSAllowed();const asset=await readMedia(e.target.file.files[0]);asset.alt=e.target.alt.value.trim();const next=[...mediaLibrary,asset];await putStore('media',next);mediaLibrary=next;await logCMS('Subida de archivo',asset.name);$('#modal').close();if(after)after(asset);else renderCMS('biblioteca');toast('Archivo guardado en este navegador')}catch(e){$('#upload-error').innerHTML=`<div class="note error">${esc(e.message)}</div>`}finally{e.submitter.disabled=false}};refreshIcons()}
function usesMedia(media){const used=[];const walk=(o,path,scope)=>{if(!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o)){if(v===media)used.push(scope+' · '+path+'.'+k);else if(typeof v==='object')walk(v,path+'.'+k,scope)}};walk(draft,'sitio','Borrador');walk(live,'sitio','Publicado');return used}
function renderLibrary(){const q=normalize($('#media-search').value),type=$('#media-type').value;const files=mediaLibrary.filter(x=>(!type||x.type===type)&&normalize(x.name+' '+x.alt).includes(q));$('#media-grid').innerHTML=files.map(x=>`<article class="library-asset">${mediaHTML(x,'library-preview',true)}<div><h3>${esc(x.name)}</h3><p>${esc(x.alt)}</p><span class="subtle">${(x.size/1024/1024).toFixed(1)} MB · ${usesMedia(x.media).length} usos</span><div class="actions"><button data-asset-info="${esc(x.id)}">Detalles</button><button data-delete-asset="${esc(x.id)}">Eliminar</button></div></div></article>`).join('')||'<div class="public-empty">Todavía no hay archivos con estos filtros. Subí tu primera imagen o video.</div>';document.querySelectorAll('[data-asset-info]').forEach(b=>b.onclick=()=>{const x=mediaLibrary.find(a=>a.id===b.dataset.assetInfo);modal('Detalles del recurso',`${mediaHTML(x,'asset-detail',true)}<h3>${esc(x.name)}</h3><p>${esc(x.alt)}</p><h3>Utilizado en</h3><ul>${usesMedia(x.media).map(u=>'<li>'+esc(u)+'</li>').join('')||'<li>Sin usos</li>'}</ul><label>Descripción accesible<input id="asset-alt" value="${esc(x.alt)}"></label><div class="actions"><button id="save-asset">Guardar metadatos</button></div>`);$('#save-asset').onclick=async()=>{try{localCMSAllowed();x.alt=$('#asset-alt').value;await putStore('media',mediaLibrary);$('#modal').close();renderLibrary();toast('Metadatos guardados')}catch(e){toast(e.message)}}});document.querySelectorAll('[data-delete-asset]').forEach(b=>b.onclick=async()=>{try{localCMSAllowed();const x=mediaLibrary.find(a=>a.id===b.dataset.deleteAsset);if(usesMedia(x.media).length)throw Error('Este recurso está en uso. Reemplazalo en el borrador y en la publicación antes de eliminarlo.');modal('Eliminar recurso sin uso',`<p>¿Eliminar «${esc(x.name)}» de esta biblioteca local?</p><div class="actions"><button id="cancel-delete">Cancelar</button><button class="primary" id="confirm-delete">Eliminar archivo</button></div>`);$('#cancel-delete').onclick=()=>$('#modal').close();$('#confirm-delete').onclick=async()=>{try{localCMSAllowed();mediaLibrary=mediaLibrary.filter(a=>a.id!==x.id);await putStore('media',mediaLibrary);await logCMS('Eliminación de archivo sin uso',x.name);$('#modal').close();renderLibrary()}catch(e){toast(e.message)}}}catch(e){toast(e.message)}});refreshIcons()}
function editEditorial(group,index){try{localCMSAllowed()}catch(e){toast(e.message);return}const isExpo=group==='exhibitions',item=index===undefined?{id:crypto.randomUUID(),title:'',text:'',date:'',end:'',time:'',room:'',category:'Conversatorios',status:'actual',published:false,virtual:false,workIds:[],media:isExpo?HERO:GALLERY,type:'image',alt:'Imagen de '+(isExpo?'exposición':'evento'),position:60}:structuredClone(draft[group][index]);modal(isExpo?'Contenido de exposición':'Evento del museo',`<form id="editorial-form"><div class="formgrid"><label class="full">Título<input name="title" required value="${esc(item.title)}"></label><label class="full">Descripción<textarea name="text" required>${esc(item.text)}</textarea></label><label>Fecha${isExpo?' de inicio':''}<input name="date" type="date" required value="${esc(item.date)}"></label>${isExpo?`<label>Fecha de cierre<input name="end" type="date" required value="${esc(item.end)}"></label><label>Sala<input name="room" value="${esc(item.room)}"></label><label>Estado<select name="status">${[['actual','Actual'],['proxima','Próxima'],['anterior','Anterior']].map(([id,n])=>`<option value="${id}" ${item.status===id?'selected':''}>${n}</option>`).join('')}</select></label><label class="full">Obras digitalizadas del recorrido<select name="works" multiple>${demo.obras.filter(o=>o.digitalizada).map(o=>`<option value="${esc(o.id)}" ${item.workIds.includes(o.id)?'selected':''}>${esc(o.titulo)}</option>`).join('')}</select></label><label class="checkbox-label"><input name="virtual" type="checkbox" ${item.virtual?'checked':''}> Disponible como exposición virtual</label>`:`<label>Hora<input name="time" type="time" required value="${esc(item.time)}"></label><label>Categoría<select name="category">${['Conversatorios','Visitas guiadas','Talleres'].map(c=>`<option ${item.category===c?'selected':''}>${c}</option>`).join('')}</select></label>`}<label class="checkbox-label"><input name="published" type="checkbox" ${item.published?'checked':''}> Visible en el sitio al publicar el borrador</label></div><p class="subtle">Este contenido editorial no modifica las reservas ni la disponibilidad de las obras en la gestión patrimonial.</p><div id="editorial-error"></div><div class="actions"><button class="primary">Guardar en borrador</button></div></form>`);$('#editorial-form').onsubmit=e=>{e.preventDefault();try{localCMSAllowed();const f=e.target;if(isExpo&&f.end.value<f.date.value)throw Error('La fecha de cierre debe ser posterior al inicio.');for(const k of ['title','text','date',...(isExpo?['end','room','status']:['time','category'])])item[k]=f.elements.namedItem(k).value.trim();item.published=f.published.checked;if(isExpo){item.virtual=f.virtual.checked;item.workIds=[...f.works.selectedOptions].map(x=>x.value);if(item.virtual&&!item.workIds.length)throw Error('Seleccioná al menos una obra digitalizada para el recorrido virtual.')}if(index===undefined)draft[group].push(item);else draft[group][index]=item;markDirty();$('#modal').close();renderCMS('contenido');toast('Contenido agregado al borrador')}catch(e){$('#editorial-error').textContent=e.message}}}
