window.addEventListener('hashchange',()=>{render().catch(e=>toast(e.message))});
(async()=>{try{await openStore();const saved=await Promise.all(['live','draft','media','audit','patrimonio'].map(getStore));if(saved[0])live=saved[0];draft=saved[1]||structuredClone(live);mediaLibrary=saved[2]||[];audit=saved[3]||[];if(saved[4])for(const k of Object.keys(demo))if(Array.isArray(saved[4][k]))demo[k]=saved[4][k];const stored=sessionStorage.getItem('museo-demo-role');if(config.mode==='demo'&&['Administrador','Director'].includes(stored)){role=stored;identity={name:role+' Demo',demo:true}}}catch(e){toast('No se pudo abrir el almacenamiento local. La edición persistente no está disponible.')}appReady=true;await render()})();
